"""Parse and format one delimited record.

See TASK.md for the rules implemented here.
"""

_QUOTE = '"'
_NL = "\n"
_CR = "\r"


def _check_delimiter(delimiter):
    if not isinstance(delimiter, str):
        raise ValueError("delimiter must be a string")
    if len(delimiter) != 1:
        raise ValueError("delimiter must be exactly one character")
    if delimiter in (_QUOTE, _NL, _CR):
        raise ValueError("delimiter must not be quote, newline or carriage return")


def parse_record(text, delimiter=","):
    """Split one delimited record into its fields. See TASK.md."""
    _check_delimiter(delimiter)
    if not isinstance(text, str):
        raise ValueError("text must be a string")

    fields = []
    i = 0
    n = len(text)

    while True:
        # Parse one field starting at position i.
        if i < n and text[i] == _QUOTE:
            # Quoted field.
            j = i + 1
            buf = []
            while True:
                if j >= n:
                    # Closing quote never came.
                    raise ValueError("unterminated quoted field")
                ch = text[j]
                if ch == _QUOTE:
                    # Either an escaped quote or the closing quote.
                    if j + 1 < n and text[j + 1] == _QUOTE:
                        buf.append(_QUOTE)
                        j += 2
                    else:
                        # Closing quote.
                        j += 1
                        break
                else:
                    buf.append(ch)
                    j += 1
            # After the closing quote: delimiter or end of text.
            if j < n:
                nxt = text[j]
                if nxt == delimiter:
                    fields.append("".join(buf))
                    i = j + 1
                    # A trailing delimiter means one more empty field.
                    continue
                if nxt in (_NL, _CR):
                    raise ValueError("newline or carriage return after closing quote")
                raise ValueError("unexpected character after closing quote")
            else:
                fields.append("".join(buf))
                return fields
        else:
            # Unquoted field: scan up to the next delimiter or end.
            # Newlines, carriage returns and quotes are invalid here.
            start = i
            while i < n and text[i] != delimiter:
                ch = text[i]
                if ch == _QUOTE:
                    raise ValueError("quote in unquoted field")
                if ch in (_NL, _CR):
                    raise ValueError("newline or carriage return outside quoted field")
                i += 1
            fields.append(text[start:i])
            if i < n:
                # We stopped on the delimiter.
                i += 1
                continue
            else:
                return fields


def format_record(fields, delimiter=","):
    """Write fields as one delimited record. See TASK.md."""
    _check_delimiter(delimiter)
    if not isinstance(fields, (list, tuple)):
        raise ValueError("fields must be a list or tuple")
    if len(fields) == 0:
        raise ValueError("fields must hold at least one field")
    for f in fields:
        if not isinstance(f, str):
            raise ValueError("every field must be a str")

    needs_quote_chars = (delimiter, _QUOTE, _NL, _CR)

    def needs_quotes(field):
        if field == "":
            return False
        if field[0] == " " or field[-1] == " ":
            return True
        for c in needs_quote_chars:
            if c in field:
                return True
        return False

    out = []
    for field in fields:
        if needs_quotes(field):
            escaped = field.replace(_QUOTE, _QUOTE + _QUOTE)
            out.append(_QUOTE + escaped + _QUOTE)
        else:
            out.append(field)
    return delimiter.join(out)
